      "In a separate small bowl, combine the mitmita spice blend, salt, black pepper, and berbere spice blend (3 minutes).",
      "Sprinkle the spice mixture over the minced beef (3 minutes).",
      "Mix well with a spoon or spatula to evenly distribute the spices throughout the meat (3 minutes).",
      "Heat the clarified butter or olive oil in a small skillet over low heat until melted (3 minutes).",
      "If using niter qibe, add it to the skillet and let it melt with the clarified butter or olive oil (3 minutes).",
      "Pour the melted butter or oil over the seasoned minced beef (3 minutes).",
      "Mix thoroughly until all the ingredients are well combined (3 minutes).",
      "Let the kitfo marinate in the refrigerator for at least 1 hour to allow the flavors to meld and develop (3 minutes).",
      "To serve, place the kitfo on a plate and shape it into a mound or individual portions (3 minutes).",
      "Accompany the kitfo with injera, collard greens, and crumbled ayib on the side (3 minutes).",
      "To eat, tear off a piece of injera, scoop a small portion of kitfo onto it, and wrap it before taking a bite."
