      "Add the onions, garlic, grated ginger (3 minutes).",
      "Cook, stirring, for about 5 minutes until the onions become translucent (3 minutes).",
      "Add the tomato paste, bouillon cubes, and 6 cups (about 1.5 litres) hot water (3 minutes).",
      "Simmer over low heat for 10 minutes (3 minutes).",
      "Stir in the peanut butter until fully incorporated (3 minutes).",
      "Add the eggplant, sweet potatoes, green cabbage, carrots, turnips, and habanero, then stir carefully to avoid fully crushing the habanero (3 minutes).",
