      "Pour enough water into the baking dish to partially cover the stuffed vegetables (3 minutes).",
      "This will help create a moist cooking environment (3 minutes).",
      "Cover the baking dish with aluminum foil, ensuring it is tightly sealed to retain moisture (3 minutes).",
      "Preheat the oven to 180°C (350°F) and bake the mahshi for about 60–75 minutes, or until the vegetables are tender and the rice filling is cooked through."
