      "Grind half of the green chillies to a paste and mix it well with the ginger and garlic pastes (3 minutes).",
      "Make cuts on the chicken pieces, rub this mixture on to them well, and marinate for about an hour at least (3 minutes).",
      "Toast coconut shavings in a pan with a little hot oil until light brown (3 minutes).",
      "Cool and grind along with half the onions to a paste (3 minutes).",
      "Heat oil in a heavy-bottomed pan and sauté the onions on medium level for about 2 minute(s) or until they are light brown in color (3 minutes).",
      "Add the remaining chopped green chillies and spice powders and fry for a few seconds (3 minutes).",
      "Add the marinated chicken pieces and fry on medium level for about 3 minutes or until they are lightly browned (3 minutes).",
      "Add the paste and salt, then mix well (3 minutes).",
      "Add water according to the desired level of consistency and bring to a boil (3 minutes).",
      "Cover and cook on low level for about 25 minute(s) or until the chicken pieces are tender and fully cooked (3 minutes).",
      "Garnish with finely-chopped coriander leaves. Cook poultry to 165°F (74°C), ground meats to 160°F (71°C), and whole cuts of pork, beef, or lamb to 145°F (63°C) with a rest before serving."
